-- =====================================================================
-- Proyecto Integrador - Segunda Entrega
-- Sistema de Gestión de Inventarios - Ferretería Aristools
-- Archivo opcional: datos_adicionales.sql  (MÁS DATOS DE PRUEBA)
-- Ejecutar DESPUÉS de aristools.sql y datos_iniciales.sql. Una sola vez.
--
-- Agrega un mes de operación realista (octubre de 2026):
--  * 18 productos nuevos en 6 categorías, una bodega de patio y una
--    bodega inactiva, 3 proveedores y 2 usuarios (uno bloqueado).
--  * Historial de movimientos para el kardex: inventario inicial,
--    compras, devoluciones, consumo interno, mermas, producto vencido y
--    dañado, devolución a proveedor, transferencias, ajustes de conteo
--    físico (+1 / -1 / -2) y una merma rechazada.
--  * 6 movimientos Pendientes para las bandejas de autorización.
--  * Alertas de bajo stock y sobrestock (activas y resueltas).
-- Las existencias finales son exactamente la suma de los movimientos
-- autorizados: el kardex cuadra con el stock.
-- Contraseña de los usuarios nuevos: Aristools2026*
-- =====================================================================

USE aristools;
START TRANSACTION;

-- Catálogos nuevos



-- Usuarios nuevos (contraseña Aristools2026*, hash BCrypt). almacen.rey queda BLOQUEADO para probar la reactivación (RF-001, RF-002).

-- Productos nuevos (HER-005 inactivo: no aparece en los combos de movimientos)

-- Historial de movimientos (octubre de 2026)

-- Existencias finales = suma de los movimientos autorizados

-- Alertas generadas por esos movimientos (RF-012)

-- La pintura PIN-001 de datos_iniciales.sql ya está por debajo de su mínimo:
-- se registra su alerta activa, calculada con el stock real.
SELECT p.id_producto, 'BAJO_STOCK', SUM(e.cantidad), p.stock_minimo, NOW(), 'ACTIVA'
FROM producto p JOIN existencia e ON e.id_producto = p.id_producto
WHERE p.codigo = 'PIN-001'
GROUP BY p.id_producto, p.stock_minimo
HAVING SUM(e.cantidad) <= p.stock_minimo;

COMMIT;
